INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-CARD-001', 'Stable angina', 'Stable angina is a clinically distinct cardiology entity: Myocardial oxygen supply-demand mismatch or acute coronary obstruction produces ischemia.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Atherosclerotic risk, diabetes, smoking, hypertension, and dyslipidemia are common risks.', 'Atherosclerotic risk, diabetes, smoking, hypertension, and dyslipidemia are common risks.', 'Myocardial oxygen supply-demand mismatch or acute coronary obstruction produces ischemia.', 'Pressure-like chest discomfort may radiate to the arm, jaw, or back; acute infarction may include diaphoresis or dyspnea.', 'Use serial ECGs and cardiac troponin with symptom timing; an initially nondiagnostic ECG does not exclude infarction.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'New shock, recurrent pain, malignant ventricular rhythm, or mechanical complication requires emergency escalation.', 'Acute ischemic syndromes need monitored emergency evaluation and reperfusion-capable consultation when indicated.', 'Outcome depends on infarct size, timely reperfusion, ventricular function, and complications.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-C-0001', 'Acute coronary syndrome', 'Acute coronary syndrome is a clinically distinct cardiology entity: Myocardial oxygen supply-demand mismatch or acute coronary obstruction produces ischemia.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Atherosclerotic risk, diabetes, smoking, hypertension, and dyslipidemia are common risks.', 'Atherosclerotic risk, diabetes, smoking, hypertension, and dyslipidemia are common risks.', 'Myocardial oxygen supply-demand mismatch or acute coronary obstruction produces ischemia.', 'Pressure-like chest discomfort may radiate to the arm, jaw, or back; acute infarction may include diaphoresis or dyspnea.', 'Use serial ECGs and cardiac troponin with symptom timing; an initially nondiagnostic ECG does not exclude infarction.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'New shock, recurrent pain, malignant ventricular rhythm, or mechanical complication requires emergency escalation.', 'Acute ischemic syndromes need monitored emergency evaluation and reperfusion-capable consultation when indicated.', 'Outcome depends on infarct size, timely reperfusion, ventricular function, and complications.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-C-0003', 'Acute pericarditis', 'Acute pericarditis is a clinically distinct cardiology entity: Inflammation, fluid accumulation, or scarring impairs pericardial function and may restrict filling.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Recent viral illness, renal failure, malignancy, autoimmune disease, trauma, and recent infarction are relevant contexts.', 'Recent viral illness, renal failure, malignancy, autoimmune disease, trauma, and recent infarction are relevant contexts.', 'Inflammation, fluid accumulation, or scarring impairs pericardial function and may restrict filling.', 'Pleuritic positional chest pain, dyspnea, or venous congestion may occur; tamponade can present with shock.', 'Positional pain and diffuse ST-segment changes favor pericarditis; bedside echocardiography identifies hemodynamic effusion.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Hypotension, rising jugular venous pressure, pulsus paradoxus, or altered perfusion demands immediate assessment.', 'Hemodynamic compromise requires emergency monitored care and procedural-capable consultation.', 'Outcome depends on etiology and hemodynamic effect; recurrent inflammation and constriction are important sequelae.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-C-0004', 'Cardiac tamponade', 'Cardiac tamponade is a clinically distinct cardiology entity: Inflammation, fluid accumulation, or scarring impairs pericardial function and may restrict filling.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Recent viral illness, renal failure, malignancy, autoimmune disease, trauma, and recent infarction are relevant contexts.', 'Recent viral illness, renal failure, malignancy, autoimmune disease, trauma, and recent infarction are relevant contexts.', 'Inflammation, fluid accumulation, or scarring impairs pericardial function and may restrict filling.', 'Pleuritic positional chest pain, dyspnea, or venous congestion may occur; tamponade can present with shock.', 'Positional pain and diffuse ST-segment changes favor pericarditis; bedside echocardiography identifies hemodynamic effusion.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Hypotension, rising jugular venous pressure, pulsus paradoxus, or altered perfusion demands immediate assessment.', 'Hemodynamic compromise requires emergency monitored care and procedural-capable consultation.', 'Outcome depends on etiology and hemodynamic effect; recurrent inflammation and constriction are important sequelae.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-C-0005', 'Cardiogenic shock', 'Cardiogenic shock is a clinically distinct cardiology entity: Transient or persistent reduction in cerebral or systemic perfusion produces syncope or shock syndromes.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Volume loss, arrhythmia, structural obstruction, autonomic triggers, medications, and cardiac outflow disease provide key context.', 'Volume loss, arrhythmia, structural obstruction, autonomic triggers, medications, and cardiac outflow disease provide key context.', 'Transient or persistent reduction in cerebral or systemic perfusion produces syncope or shock syndromes.', 'Abrupt loss of consciousness or hypotension is interpreted with posture, prodrome, exertion, ECG, and recovery pattern.', 'Exertional syncope, absent prodrome, abnormal ECG, family sudden-death history, or persistent hypotension favors high-risk cardiac disease.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Ongoing hypotension, chest pain, dyspnea, neurologic deficit, or abnormal rhythm requires emergency monitoring.', 'High-risk syncope and shock need monitored evaluation directed at the suspected mechanism.', 'Prognosis is benign in typical reflex syncope but worsens sharply with structural heart disease or malignant arrhythmia.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-C-0006', 'Atrial fibrillation', 'Atrial fibrillation is a clinically distinct cardiology entity: Abnormal impulse formation or conduction alters rate, rhythm, and cardiac output.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Structural heart disease, ischemia, electrolyte disturbance, stimulants, medications, inherited channelopathy, and hypoxia can precipitate rhythm disease.', 'Structural heart disease, ischemia, electrolyte disturbance, stimulants, medications, inherited channelopathy, and hypoxia can precipitate rhythm disease.', 'Abnormal impulse formation or conduction alters rate, rhythm, and cardiac output.', 'Palpitations, presyncope, syncope, chest discomfort, or dyspnea may occur; some rhythms are incidental.', 'ECG rhythm morphology, QRS width, regularity, pre-excitation, QT interval, and stability determine the safe pathway.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Hypotension, ischemic discomfort, acute heart failure, altered mental status, or a pulseless rhythm requires immediate resuscitation.', 'Unstable perfusing tachyarrhythmia requires synchronized cardioversion; pulseless VF or VT requires defibrillation and CPR.', 'Risk ranges from benign ectopy to sudden death; structural heart disease and inherited syndromes change risk.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
