INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-CARD-027', 'Thoracic aortic aneurysm', 'Thoracic aortic aneurysm is a clinically distinct cardiology entity: Disease of the aortic wall or severe blood-pressure elevation can threaten perfusion or rupture.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Hypertension, smoking, atherosclerosis, heritable aortopathy, and older age are important patterns.', 'Hypertension, smoking, atherosclerosis, heritable aortopathy, and older age are important patterns.', 'Disease of the aortic wall or severe blood-pressure elevation can threaten perfusion or rupture.', 'Abrupt severe chest, back, abdominal, or limb symptoms can signal acute aortic disease.', 'Pulse or blood-pressure asymmetry, neurologic deficit, tearing pain, or end-organ injury redirects evaluation from uncomplicated pain.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Hypotension, malperfusion, neurologic deficit, or suspected rupture is an emergency.', 'Suspected acute aortic syndromes require monitored care, urgent imaging, and specialty consultation.', 'Rupture and malperfusion carry high mortality; surveillance and risk-factor control matter for stable disease.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
