INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-CARD-030', 'Acute limb ischemia', 'Acute limb ischemia is a clinically distinct cardiology entity: Arterial obstruction, embolization, or chronic atherosclerotic narrowing impairs tissue perfusion.', 'Cardiology', '2', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Smoking, diabetes, hyperlipidemia, atrial fibrillation, aneurysmal disease, and recent vascular instrumentation are important risks.', 'Smoking, diabetes, hyperlipidemia, atrial fibrillation, aneurysmal disease, and recent vascular instrumentation are important risks.', 'Arterial obstruction, embolization, or chronic atherosclerotic narrowing impairs tissue perfusion.', 'Exertional limb symptoms, rest pain, abrupt pain, coolness, or skin changes reflect the tempo and territory of ischemia.', 'Acute pain with pulselessness or neurologic deficit differs from chronic claudication and requires urgent vascular assessment.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Threatened limb, sensory or motor deficit, hypotension, or suspected embolic source is emergent.', 'Acute limb threat needs immediate vascular consultation; chronic disease requires risk reduction and revascularization assessment when indicated.', 'Tissue loss, recurrent embolism, cardiovascular events, and renal injury shape outcome.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
