INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-CARD-045', 'Arrhythmogenic right ventricular cardiomyopathy', 'Arrhythmogenic right ventricular cardiomyopathy is a clinically distinct cardiology entity: Abnormal impulse formation or conduction alters rate, rhythm, and cardiac output.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Structural heart disease, ischemia, electrolyte disturbance, stimulants, medications, inherited channelopathy, and hypoxia can precipitate rhythm disease.', 'Structural heart disease, ischemia, electrolyte disturbance, stimulants, medications, inherited channelopathy, and hypoxia can precipitate rhythm disease.', 'Abnormal impulse formation or conduction alters rate, rhythm, and cardiac output.', 'Palpitations, presyncope, syncope, chest discomfort, or dyspnea may occur; some rhythms are incidental.', 'ECG rhythm morphology, QRS width, regularity, pre-excitation, QT interval, and stability determine the safe pathway.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Hypotension, ischemic discomfort, acute heart failure, altered mental status, or a pulseless rhythm requires immediate resuscitation.', 'Unstable perfusing tachyarrhythmia requires synchronized cardioversion; pulseless VF or VT requires defibrillation and CPR.', 'Risk ranges from benign ectopy to sudden death; structural heart disease and inherited syndromes change risk.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
