INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-CARD-076', 'Prosthetic-valve endocarditis', 'Prosthetic-valve endocarditis is a clinically distinct cardiology entity: Inflammatory or infectious valvular lesions can embolize, destroy tissue, or impair valve function.', 'Cardiology', '2', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Bacteremia risk, prosthetic material, injection drug use, congenital lesions, autoimmune disease, and malignancy alter pretest probability.', 'Bacteremia risk, prosthetic material, injection drug use, congenital lesions, autoimmune disease, and malignancy alter pretest probability.', 'Inflammatory or infectious valvular lesions can embolize, destroy tissue, or impair valve function.', 'Fever with a new murmur, embolic event, or systemic inflammatory findings should prompt targeted evaluation.', 'Repeated blood cultures and echocardiography are complementary; culture-negative disease requires exposure and serologic context.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Heart failure, conduction disturbance, persistent bacteremia, embolic events, or prosthetic involvement demands urgent specialty involvement.', 'Suspected infective disease needs inpatient cultures before directed antimicrobial decisions when feasible and early multidisciplinary consultation.', 'Outcome depends on organism, valve destruction, embolic burden, and timing of definitive intervention.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
