INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-CARD-094', 'Bicuspid aortic valve', 'Bicuspid aortic valve is a clinically distinct cardiology entity: Valve obstruction or regurgitation creates pressure or volume overload and characteristic flow findings.', 'Cardiology', '2', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Degeneration, congenital anatomy, rheumatic disease, ischemia, infection, connective-tissue disease, and prosthetic dysfunction are major causes.', 'Degeneration, congenital anatomy, rheumatic disease, ischemia, infection, connective-tissue disease, and prosthetic dysfunction are major causes.', 'Valve obstruction or regurgitation creates pressure or volume overload and characteristic flow findings.', 'Exertional dyspnea, fatigue, chest pain, syncope, or edema may appear as lesions become severe.', 'Murmur timing, radiation, response to maneuvers, ventricular response, and echocardiography distinguish lesions.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Acute severe regurgitation, syncope, pulmonary edema, endocarditis, or shock needs urgent specialty evaluation.', 'Symptomatic or severe structural disease warrants cardiology and valve-team assessment for repair or replacement principles.', 'Outcome relates to lesion severity, ventricular remodeling, pulmonary pressures, rhythm, and intervention timing.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-CARD-095', 'Obstructive shock', 'Obstructive shock is a clinically distinct cardiology entity: Transient or persistent reduction in cerebral or systemic perfusion produces syncope or shock syndromes.', 'Cardiology', '1', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Volume loss, arrhythmia, structural obstruction, autonomic triggers, medications, and cardiac outflow disease provide key context.', 'Volume loss, arrhythmia, structural obstruction, autonomic triggers, medications, and cardiac outflow disease provide key context.', 'Transient or persistent reduction in cerebral or systemic perfusion produces syncope or shock syndromes.', 'Abrupt loss of consciousness or hypotension is interpreted with posture, prodrome, exertion, ECG, and recovery pattern.', 'Exertional syncope, absent prodrome, abnormal ECG, family sudden-death history, or persistent hypotension favors high-risk cardiac disease.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Ongoing hypotension, chest pain, dyspnea, neurologic deficit, or abnormal rhythm requires emergency monitoring.', 'High-risk syncope and shock need monitored evaluation directed at the suspected mechanism.', 'Prognosis is benign in typical reflex syncope but worsens sharply with structural heart disease or malignant arrhythmia.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
